from google.cloud import kms_v1
import os

class KmsClientHelper:
    """Helper class for Google Cloud KMS client initialization and common configurations."""

    def __init__(self):
        self.project_id = os.environ.get("GOOGLE_CLOUD_PROJECT_ID")
        self.location = os.environ.get("GOOGLE_CLOUD_KMS_LOCATION", "global")
        self.key_ring = os.environ.get("GOOGLE_CLOUD_KMS_KEY_RING")
        self.key_name = os.environ.get("GOOGLE_CLOUD_KMS_KEY_NAME")
        self.key_version = os.environ.get("GOOGLE_CLOUD_KMS_KEY_VERSION")

        if not self.project_id or not self.key_ring or not self.key_name:
            raise ValueError("Missing Google Cloud KMS environment variables. Ensure GOOGLE_CLOUD_PROJECT_ID, GOOGLE_CLOUD_KMS_KEY_RING, and GOOGLE_CLOUD_KMS_KEY_NAME are set.")

        self.client = kms_v1.KeyManagementServiceClient()

    def get_client(self) -> kms_v1.KeyManagementServiceClient:
        return self.client

    def get_key_path(self, key_name: str = None, key_ring: str = None, location: str = None) -> str:
        return self.client.crypto_key_path(
            self.project_id,
            location or self.location,
            key_ring or self.key_ring,
            key_name or self.key_name,
        )

    def get_crypto_key_version_path(self, key_name: str = None, key_ring: str = None, location: str = None, key_version: str = None) -> str:
        return self.client.crypto_key_version_path(
            self.project_id,
            location or self.location,
            key_ring or self.key_ring,
            key_name or self.key_name,
            key_version or self.key_version
        )

import dataclasses
from typing import Optional, Literal

@dataclasses.dataclass
class EncryptionRequest:
    plaintext: bytes
    key_id: Optional[str] = None  # Full KMS key path or identifier

@dataclasses.dataclass
class EncryptionResponse:
    ciphertext: bytes
    encrypted_dek: Optional[bytes] = None # For envelope encryption

@dataclasses.dataclass
class DecryptionRequest:
    ciphertext: bytes
    key_id: Optional[str] = None # Full KMS key path or identifier
    encrypted_dek: Optional[bytes] = None # For envelope encryption

@dataclasses.dataclass
class DecryptionResponse:
    plaintext: bytes

@dataclasses.dataclass
class SignatureRequest:
    message: bytes
    key_id: Optional[str] = None # Full KMS key path or identifier
    key_version_id: Optional[str] = None # Specific key version for signing

@dataclasses.dataclass
class SignatureResponse:
    signature: bytes

@dataclasses.dataclass
class VerificationRequest:
    message: bytes
    signature: bytes
    key_id: Optional[str] = None # Full KMS key path or identifier
    key_version_id: Optional[str] = None # Specific key version for verification

@dataclasses.dataclass
class VerificationResponse:
    is_valid: bool

from google.cloud import dlp_v2
import os

def check_payload_safety(project_id: str, text_payload: str, info_types: list[str] = None) -> dict:
    """Checks decrypted text payloads for unsafe content using Google Cloud DLP.

    Args:
        project_id: Your Google Cloud project ID.
        text_payload: The decrypted text payload to scan.
        info_types: A list of info types to scan for (e.g., ["EMAIL_ADDRESS", "PHONE_NUMBER"]).
                    If None, a default set of common info types will be used.

    Returns:
        A dictionary containing the DLP inspection results.
    """
    dlp_client = dlp_v2.DlpServiceClient()
    project_path = f"projects/{project_id}"

    if info_types is None:
        info_types = ["CREDIT_CARD_NUMBER", "EMAIL_ADDRESS", "PHONE_NUMBER", "US_SOCIAL_SECURITY_NUMBER"]

    # Convert info_types list to DlpV2InfoType objects
    inspect_info_types = [{"name": itype} for itype in info_types]

    item = {"value": text_payload}

    inspect_config = {
        "info_types": inspect_info_types,
        "min_likelihood": dlp_v2.Likelihood.POSSIBLE,
        "limits": {"max_findings_per_request": 0} # 0 means no limit
    }

    try:
        response = dlp_client.inspect_content(
            request={
                "parent": project_path,
                "inspect_config": inspect_config,
                "item": item,
            }
        )
        findings = []
        if response.result and response.result.findings:
            for finding in response.result.findings:
                findings.append({
                    "info_type": finding.info_type.name,
                    "likelihood": dlp_v2.Likelihood(finding.likelihood).name,
                    "quote": finding.quote,
                })
        return {"findings": findings, "success": True}

    except Exception as e:
        return {"error": str(e), "success": False}
